Lemma bil_unlive_neq : forall bil b vsc ps lps L e, p_cmap vsc = 0 -> p_data vsc <> 0 -> In e (bil_unlive bil b vsc ps lps L) ->
  fst e <> bil /\ fst e <> b_lineset b /\ ~ In (fst e) lps /\ fst e <> b_kfract b /\ fst e <> b_kindex b /\ fst e <> b_nc b
  /\ fst e <> b_range b /\ fst e <> b_spatial b /\ fst e <> b_pixac b /\ fst e <> b_ba b /\ fst e <> b_barr b /\ fst e <> b_parr b
